repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('hill', 24), ('upper', 56), ('upper', 6), ('upper', 4), ('river', 22), ('lower', 31), ('river', 35)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.ranking.py:
"""Codes of harvests in order."""


def ranked_codes(harvests):
    """Return the kilos of each harvest as a text code, from the lowest number to the highest."""
    return sorted(str(x.kilos) for x in harvests)


def code_of(harvest):
    """Return the text code of one harvest."""
    return str(harvest.kilos)


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names

repo.tests/test_visible.py:
from harvests import Harvest
from ranking import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Harvest("a", 10), Harvest("b", 9)]) == ["9", "10"]


def test_single_digits():
    assert ranked_codes([Harvest("a", 3), Harvest("b", 1), Harvest("c", 2)]) == ["1", "2", "3"]
